-- CHAMBA 042 — Panel Equipo admin (técnicos/clientes) sin depender de JWTSET statement_timeout = '120s';CREATE OR REPLACE FUNCTION DROP FUNCTION IF EXISTS get_admin_team_profiles CASCADE;CREATE OR REPLACE FUNCTION get_admin_team_profiles(  p_admin_id UUID,  p_role TEXT DEFAULT NULL)RETURNS JSONBLANGUAGE plpgsqlSECURITY DEFINERSET search_path = publicAS $$BEGIN  IF p_admin_id IS NULL THEN    RETURN '[]'::jsonb;  END IF;  IF NOT EXISTS (    SELECT 1 FROM profiles p    WHERE p.id = p_admin_id AND p.role::text = 'admin'  ) THEN    RETURN '[]'::jsonb;  END IF;  RETURN COALESCE((    SELECT jsonb_agg(to_jsonb(p) ORDER BY p.created_at DESC)    FROM profiles p    WHERE p.role::text IN ('worker', 'client')      AND (p_role IS NULL OR p_role = '' OR p.role::text = p_role)  ), '[]'::jsonb);END;$$;GRANT EXECUTE ON FUNCTION get_admin_team_profiles(UUID, TEXT) TO anon, authenticated;CREATE OR REPLACE FUNCTION DROP FUNCTION IF EXISTS admin_set_profile_approval CASCADE;CREATE OR REPLACE FUNCTION admin_set_profile_approval(  p_admin_id UUID,  p_profile_id UUID,  p_approve BOOLEAN,  p_role TEXT DEFAULT 'worker')RETURNS JSONBLANGUAGE plpgsqlSECURITY DEFINERSET search_path = publicAS $$DECLARE  v_row profiles%ROWTYPE;BEGIN  IF p_admin_id IS NULL OR p_profile_id IS NULL THEN    RETURN jsonb_build_object('success', false, 'error', 'Parámetros requeridos');  END IF;  IF NOT EXISTS (    SELECT 1 FROM profiles p    WHERE p.id = p_admin_id AND p.role::text = 'admin'  ) THEN    RETURN jsonb_build_object('success', false, 'error', 'Solo administradores');  END IF;  IF p_role NOT IN ('worker', 'client') THEN    RETURN jsonb_build_object('success', false, 'error', 'Rol no válido');  END IF;  UPDATE profiles  SET    is_approved = p_approve,    worker_status = CASE      WHEN p_role = 'worker' AND p_approve THEN 'active'      WHEN p_role = 'worker' AND NOT p_approve THEN 'suspended'      ELSE worker_status    END,    category_1_approved = CASE      WHEN p_role = 'worker' AND p_approve THEN TRUE      ELSE category_1_approved    END,    updated_at = NOW()  WHERE id = p_profile_id    AND role::text = p_role  RETURNING * INTO v_row;  IF NOT FOUND THEN    RETURN jsonb_build_object('success', false, 'error', 'Perfil no encontrado');  END IF;  RETURN jsonb_build_object('success', true, 'profile', to_jsonb(v_row));END;$$;GRANT EXECUTE ON FUNCTION admin_set_profile_approval(UUID, UUID, BOOLEAN, TEXT) TO anon, authenticated;CREATE OR REPLACE FUNCTION DROP FUNCTION IF EXISTS admin_set_worker_category2 CASCADE;CREATE OR REPLACE FUNCTION admin_set_worker_category2(  p_admin_id UUID,  p_worker_id UUID,  p_approve BOOLEAN)RETURNS JSONBLANGUAGE plpgsqlSECURITY DEFINERSET search_path = publicAS $$DECLARE  v_row profiles%ROWTYPE;BEGIN  IF p_admin_id IS NULL OR p_worker_id IS NULL THEN    RETURN jsonb_build_object('success', false, 'error', 'Parámetros requeridos');  END IF;  IF NOT EXISTS (    SELECT 1 FROM profiles p    WHERE p.id = p_admin_id AND p.role::text = 'admin'  ) THEN    RETURN jsonb_build_object('success', false, 'error', 'Solo administradores');  END IF;  UPDATE profiles  SET category_2_approved = p_approve, updated_at = NOW()  WHERE id = p_worker_id AND role::text = 'worker'  RETURNING * INTO v_row;  IF NOT FOUND THEN    RETURN jsonb_build_object('success', false, 'error', 'Técnico no encontrado');  END IF;  RETURN jsonb_build_object('success', true, 'profile', to_jsonb(v_row));END;$$;GRANT EXECUTE ON FUNCTION admin_set_worker_category2(UUID, UUID, BOOLEAN) TO anon, authenticated;